private static List<TimeRange> mergeRanges(List<TimeRange> left, List<TimeRange> right) {
    List<TimeRange> result = new ArrayList<>();
    int leftIndex = 0;
    int rightIndex = 0;
    while (leftIndex < left.size() && rightIndex < right.size()) {
        TimeRange leftRange = left.get(leftIndex);
        TimeRange rightRange = right.get(rightIndex);
        if (leftRange.getStart() < rightRange.getStart()) {
            result.add(leftRange);
            leftIndex++;
        } else if (leftRange.getStart() > rightRange.getStart()) {
            result.add(rightRange);
            rightIndex++;
        } else {
            long end = Math.max(leftRange.getEnd(), rightRange.getEnd());
            if (end > leftRange.getEnd() && end > rightRange.getEnd()) {
                result.add(new TimeRange(leftRange.getStart(), end));
            } else {
                result.add(leftRange);
                result.add(rightRange);
            }
            leftIndex++;
            rightIndex++;
        }
    }
    result.addAll(left.subList(leftIndex, left.size()));
    result.addAll(right.subList(rightIndex, right.size()));
    return result;
}

