public GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph) {
    // Initialize the graph path
    GraphPath<V,E> path = new GraphPath<V,E>(graph);

    // Iterate over the edges in the tour set
    for (E edge : tour) {
        // Add the edge to the path
        path.addEdge(edge);

        // Get the vertices of the edge
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        // Add the source vertex to the path
        path.addVertex(graph.getEdgeSource(edge));

        // If the source and target are not equal, add the target vertex to the path
        if (!source.equals(target)) {
            path.addVertex(graph.getEdgeTarget(edge));
        }
    }

    // Return the transformed graph path
    return path;
}

