 * Remove the non-null {@code node} from the list.
 */
private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    // Get the previous and next nodes
    ListNodeImpl<E> prev = node.prev;
    ListNodeImpl<E> next = node.next;
    // Check if the node is the first or last node
    if (prev == null) {
        // The node is the first node, so set the new first node
        first = next;
    } else {
        // Advance the previous node's next pointer
        prev.next = next;
    }
    if (next == null) {
        // The node is the last node, so set the new last node
        last = prev;
    } else {
        // Advance the next node's previous pointer
        next.prev = prev;
    }
    // Null out the node's next and previous pointers
    node.prev = null;
    node.next = null;
    size--;
    return true;
}

private boolean unlink(ListNodeImpl<E> node) {
    if (node.next != null) {
        // Remove the node from the list
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    // Check if the node was the last node in the list
    if (node.next == null) {
        // The list is now empty
        last = null;
    }

    // Decrement the size of the list
    size--;

    // Return true if the node was successfully removed
    return true;
}

