public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

List<ThreadSnapshot> threadSnapshots = new ArrayList<>(); 
for (ProfileAnalyzeTimeRange timeRange : timeRanges) {

  // Read the thread dump file a line at a time
  try (BufferedReader reader = new BufferedReader(new FileReader(file))) {

    // Skip the header line
    reader.readLine();

    // Loop through the rest of the lines
    String line;
    while ((line = reader.readLine()) != null) {

      // Get the thread name and ID
      String threadName = line.split(" ")[0];
      int threadId = Integer.parseInt(line.split(" ")[1].split(":")[0]);

      // Get the stack trace lines
      List<StackTraceElement> stackTrace = new ArrayList<>();
      boolean inStackTrace = false;
      while ((line = reader.readLine()) != null && !line.matches("[\\s-]+")) {
        if (line.matches("at .*\\(.*\\)")) {
          inStackTrace = true;
        } else if (inStackTrace && line.matches(" - ")) {
          inStackTrace = false;
        }
        if (inStackTrace) {
          stackTrace.add(new StackTraceElement(line));
        }
      }

      // Get the current time in milliseconds
      long time = System.currentTimeMillis();

      // Check if the time range intersects with the thread dump time
      if (timeRange.getStart() <= time && time <= timeRange.getEnd()) {

        // Add the thread snapshot to the list
        threadSnapshots.add(new ThreadSnapshot(threadName, threadId, stackTrace));
      }
    }
  }
}

return threadSnapshots;
}

/***
 * load thread snapshots in appointing time range
 */
public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    BufferedReader reader = new BufferedReader(new FileReader(file));
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    String line;
    while ((line = reader.readLine()) != null) {
        if (line.startsWith("#") || line.isEmpty()) {
            continue;
        }
        String[] fields = line.split(" ");
        if (fields.length < 4) {
            continue;
        }
        long timeStamp = Long.parseLong(fields[0]);
        String event = fields[1];
        int threadId = Integer.parseInt(fields[2]);
        int threadName = Integer.parseInt(fields[3]);
        ThreadSnapshot snapshot = new ThreadSnapshot(timeStamp, event, threadId, threadName);
        threadSnapshots.add(snapshot);
    }
    reader.close();
    // filter thread snapshots with specified time range
    long minTime = 0, maxTime = 0;
    for (ProfileAnalyzeTimeRange range : timeRanges) {
        minTime = Math.min(minTime, range.getStart());
        maxTime = Math.max(maxTime, range.getEnd());
    }
    List<ThreadSnapshot> result = new ArrayList<>();
    for (ThreadSnapshot snapshot : threadSnapshots) {
        if (snapshot.getTimeStamp() >= minTime && snapshot.getTimeStamp() <= maxTime) {
            result.add(snapshot);
        }
    }
    return result;
}
